css:
/* From Uiverse.io by Cobp  - Tags: material design, blue, pink, input, search, shadow, html, css */
.__UIV_SCOPE__ .container {
  --foreground-color-1: rgba(225, 225, 225, 0.5);
  --foreground-color-3: rgba(98, 98, 98, 0.3);
  --foreground-color-2: #ffffff;
  --background-color-1: #070807;
  position: relative;
  padding: 2px;
  border-radius: 16px;
  background-image: linear-gradient(
    325deg,
    #4d3acd 0%,
    #4d3acd 10%,
    rgba(98, 98, 98, 0.3) 25%,
    rgba(98, 98, 98, 0.3) 50%,
    rgba(98, 98, 98, 0.3) 75%,
    #cd3aad 90%,
    #cd3aad 100%
  );
}
.__UIV_SCOPE__ .container::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  background-color: #ffffff;
  width: 60px;
  height: 30px;
  border-radius: 14px 50% 0 10px;
  z-index: -1;
  box-shadow: 0 0 4px #ffffff, 0 0 50px 1px #ffffff, 0 0 50px 10px #cd3aad;
}
.__UIV_SCOPE__ .container::before {
  content: "";
  position: absolute;
  bottom: 0;
  right: 0;
  background-color: #ffffff;
  width: 60px;
  height: 30px;
  border-radius: 0 10px 14px 50%;
  z-index: -1;
  box-shadow: 0 0 4px #ffffff, 0 0 10px 1px #ffffff, 0 0 50px 10px #4d3acd;
}
.__UIV_SCOPE__ .shadow-container {
  position: absolute;
  border-radius: 16px;
  background-image: linear-gradient(
    325deg,
    #3b82f6 0%,
    #3b82f6 20%,
    transparent 25%,
    transparent 50%,
    transparent 75%,
    #cd3aad 80%,
    #cd3aad 100%
  );
  filter: blur(40px);
  inset: 0;
  transition: all 0.3s ease-in-out;
  z-index: -1;
}
.__UIV_SCOPE__ .search-bar {
  padding: 8px;
  background-color: var(--background-color-1);
  color: var(--foreground-color-1);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  cursor: text;
}
.__UIV_SCOPE__ .icon {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .icon svg {
  padding: 4px;
}
.__UIV_SCOPE__ .icon.filter {
  border: 2px solid transparent;
  background-image: linear-gradient(
    to top,
    #5b5b5b 0%,
    #070807 40%,
    #070807 60%,
    #5b5b5b 100%
  );
  border-radius: 8px;
  color: var(--foreground-color-2);
  cursor: pointer;
}
.__UIV_SCOPE__ .icon.filter svg {
  border-radius: 6px;
  background-color: var(--background-color-1);
  box-shadow: inset 0 3px 3px -2px #424242, inset 0 -3px 3px -2px #424242;
  transition: all 0.3s ease;
}
.__UIV_SCOPE__ .icon.filter:hover svg {
  scale: 1.1;
}
.__UIV_SCOPE__ .input {
  margin-left: 5px;
  background-color: transparent;
  border: none;
  outline: none;
  caret-color: var(--foreground-color-2);
  color: var(--foreground-color-2);
  font-size: 14px;
}
